def f(g):
    h=len(g[0]); s=g[0].index(2); last=min(s,h-1-s)
    out=[[0]*h for _ in range(h)]
    for r in range(h):
        for c in range(h):
            if (c-r-s)%4==0 and (r>last or s-r<c<s+r): out[r][c]=1
    for r in range(h):
        for c in (s-r,s+r):
            if 0<=c<h: out[r][c]=2
    return out
